def count_inv(a):
    if len(a) <= 1:
        return a, 0
    m = len(a) // 2
    l, cl = count_inv(a[:m])
    r, cr = count_inv(a[m:])
    out, i, j, c = [], 0, 0, cl + cr
    while i < len(l) and j < len(r):
        if l[i] <= r[j]:
            out.append(l[i]); i += 1
        else:
            out.append(r[j]); j += 1; c += len(l) - i
    return out + l[i:] + r[j:], c

