def det(m):
    n = len(m)
    if n == 1:
        return m[0][0]
    if n == 2:
        return det2(m)
    total = 0
    for j in range(n):
        minor = [row[:j] + row[j+1:] for row in m[1:]]
        total += ((-1) ** j) * m[0][j] * det(minor)
    return total

