class Cart:
    def __init__(self, orders):
        self.orders = orders

    def total(self):
        return sum(o.amount() for o in self.orders)

    def discount_by_category(self, rate_by_category):
        total = 0.0
        for o in self.orders:
            rate = rate_by_category.get(o.category, 0.0)
            total += o.amount() * (1 - rate)
        return total


